import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Hiến chương Văn minh Cộng sinh","description":"","frontmatter":{},"headers":[],"relativePath":"vi/03-共生文明宪章.md","filePath":"vi/03-共生文明宪章.md","lastUpdated":null}'),a={name:"vi/03-共生文明宪章.md"};function g(u,n,l,o,r,s){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="hien-chuong-van-minh-cong-sinh" tabindex="-1">Hiến chương Văn minh Cộng sinh <a class="header-anchor" href="#hien-chuong-van-minh-cong-sinh" aria-label="Permalink to &quot;Hiến chương Văn minh Cộng sinh&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>03</td></tr><tr><td>Mô-đun</td><td>Nguyên tắc chung và Cài đặt cốt lõi</td></tr><tr><td>Từ khóa chính</td><td>Hiến chương, Luật cơ bản, Thể chế Cộng sinh, Cộng hòa Muôn tộc, Quyền và Nghĩa vụ</td></tr></tbody></table><h2 id="_1-đia-vi-va-ban-chat-cua-hien-chuong" tabindex="-1">1. Địa vị và Bản chất của Hiến chương <a class="header-anchor" href="#_1-đia-vi-va-ban-chat-cua-hien-chuong" aria-label="Permalink to &quot;1. Địa vị và Bản chất của Hiến chương&quot;">​</a></h2><p>Hiến chương Văn minh Cộng sinh là luật pháp cơ bản của Văn minh Cộng sinh Neo trong Vũ trụ Nguyên bản Mười nghìn Linh hồn và Neo Cân bằng, và là cơ sở tối cao của mọi luật pháp, thể chế và chính sách. Hiến chương lấy &quot;Tuyên ngôn Văn minh Cộng sinh Neo&quot; làm tiền thân tinh thần, và cụ thể hóa những chủ trương cốt lõi của tuyên ngôn thành các chuẩn mực pháp lý có tính cưỡng chế. Hiệu lực của hiến chương bao gồm tất cả các chủng tộc, vị diện và cá thể tham gia vào văn minh cộng sinh trong Heng Yuan Zhou, và mọi quy định địa phương, quy tắc tông môn hay phong tục chủng tộc nào mâu thuẫn với hiến chương đều là vô hiệu.</p><p>Bản chất của hiến chương có thể được tóm tắt trong ba điểm: thứ nhất, nó là một hợp đồng văn minh, là sự đồng thuận cơ bản đạt được giữa Muôn tộc về tiến hóa cộng sinh; thứ hai, nó là một bản bảo đảm quyền, quy định rõ ràng các quyền và tự do cơ bản của mỗi sự sống trong văn minh cộng sinh; và thứ ba, nó là một luật hạn chế quyền lực, đặt ra những ranh giới không thể vượt qua cho quyền lực của các cơ quan cai trị văn minh.</p><h2 id="_2-cac-nguyen-tac-co-ban-cua-hien-chuong" tabindex="-1">2. Các Nguyên tắc Cơ bản của Hiến chương <a class="header-anchor" href="#_2-cac-nguyen-tac-co-ban-cua-hien-chuong" aria-label="Permalink to &quot;2. Các Nguyên tắc Cơ bản của Hiến chương&quot;">​</a></h2><p>Hiến chương thiết lập sáu nguyên tắc cơ bản sau, xuyên suốt tất cả các điều khoản:</p><ol><li><strong>Nguyên tắc Cộng sinh tối thượng</strong>: mục tiêu tối cao của mọi thiết kế thể chế và việc thực thi quyền lực là thúc đẩy tiến hóa cộng sinh của Muôn tộc. Khi lợi ích cá thể xung đột với lợi ích cộng sinh tập thể, lợi ích cộng sinh được ưu tiên, nhưng cá thể phải được bồi thường hợp lý và cung cấp con đường thay thế.</li><li><strong>Nguyên tắc Chống cướp bóc</strong>: hiến chương cấm mọi hình thức hành vi cướp bóc, bao gồm nhưng không giới hạn ở cướp bóc năng lượng, nuốt chửng nguyên bản, nô lệ hóa tinh thần, và độc quyền tài nguyên. Mọi hệ thống tu luyện lấy cướp bóc làm cốt lõi đều bị tuyên bố là bất hợp pháp.</li><li><strong>Nguyên tắc Bình đẳng quyền tiến hóa</strong>: tất cả sự sống đều bình đẳng trước quyền tiến hóa, không bị phân biệt đối xử do chủng tộc, hình thái, xuất thân hay mức độ tu luyện ban đầu. Nhà nước và văn minh có nghĩa vụ cung cấp hỗ trợ tiến hóa bổ sung cho các nhóm yếu thế.</li><li><strong>Nguyên tắc Nhiều lao động, nhiều thưởng</strong>: việc phân bổ tài nguyên tiến hóa chủ yếu dựa trên đóng góp của cá thể vào mạng lưới cộng sinh; đóng góp càng lớn, tài nguyên và hỗ trợ nhận được càng nhiều. Đồng thời, thiết lập đường bảo đảm cơ bản, đảm bảo rằng ngay cả những cá thể có đóng góp ít hơn cũng có thể có được điều kiện tiến hóa cơ bản.</li><li><strong>Nguyên tắc Kết hợp Tự trị và Cộng trị</strong>: mỗi chủng tộc được hưởng quyền tự trị trong các vấn đề nội bộ miễn là không vi phạm hiến chương; các vấn đề công cộng xuyên chủng tộc và xuyên vị diện được cộng trị bởi các cơ quan Cộng hòa Muôn tộc.</li><li><strong>Nguyên tắc Hiện thực làm nền tảng</strong>: mọi thiết kế thể chế của hiến chương đều lấy thế giới thực làm cơ sở thực tế duy nhất; không thừa nhận rằng bất kỳ mối quan hệ quyền và nghĩa vụ nào trong thế giới hư cấu có thể đặt lên trên hiện thực.</li></ol><h2 id="_3-cau-truc-co-ban-cua-hien-chuong" tabindex="-1">3. Cấu trúc Cơ bản của Hiến chương <a class="header-anchor" href="#_3-cau-truc-co-ban-cua-hien-chuong" aria-label="Permalink to &quot;3. Cấu trúc Cơ bản của Hiến chương&quot;">​</a></h2><p>Hiến chương bao gồm sáu phần: lời nói đầu, nguyên tắc chung, quyền và nghĩa vụ cơ bản, cơ quan văn minh, hệ thống pháp luật, và quy trình sửa đổi:</p><table tabindex="0"><thead><tr><th>Phần</th><th>Nội dung cốt lõi</th><th>Số điều khoản</th></tr></thead><tbody><tr><td>Lời nói đầu</td><td>Làm rõ bối cảnh lịch sử, nguồn gốc tinh thần và mục tiêu tối hậu của hiến chương</td><td>Không đánh số</td></tr><tr><td>Nguyên tắc chung</td><td>Quy định bản chất của văn minh, quan điểm vũ trụ, thể chế cốt lõi và chính sách cơ bản</td><td>30 điều</td></tr><tr><td>Quyền và nghĩa vụ cơ bản</td><td>Quy định các quyền cơ bản của sự sống như quyền tiến hóa, quyền biết tin, quyền tham gia, và các nghĩa vụ tương ứng</td><td>50 điều</td></tr><tr><td>Cơ quan văn minh</td><td>Quy định tổ chức và thẩm quyền của các cơ quan như Nghị viện Cộng hòa Muôn tộc, Ủy ban Hành chính Cộng sinh, Tòa án Neo</td><td>40 điều</td></tr><tr><td>Hệ thống pháp luật</td><td>Quy định thẩm quyền lập pháp và quy tắc áp dụng của luật lao động, luật bảo vệ người tiêu dùng và năm luật bổ trợ dưới hiến pháp</td><td>20 điều</td></tr><tr><td>Quy trình sửa đổi</td><td>Quy định quy trình đề xuất, xem xét, bỏ phiếu và có hiệu lực của việc sửa đổi hiến chương</td><td>10 điều</td></tr></tbody></table><h2 id="_4-quyen-va-nghia-vu-co-ban" tabindex="-1">4. Quyền và Nghĩa vụ Cơ bản <a class="header-anchor" href="#_4-quyen-va-nghia-vu-co-ban" aria-label="Permalink to &quot;4. Quyền và Nghĩa vụ Cơ bản&quot;">​</a></h2><p>Các quyền cơ bản cốt lõi do hiến chương quy định bao gồm:</p><ul><li><strong>Quyền lựa chọn tiến hóa</strong>: mỗi sự sống có quyền tự do lựa chọn hệ thống tu luyện và con đường tiến hóa của mình, không ai được cưỡng bức</li><li><strong>Quyền tiếp cận hệ thống</strong>: mỗi sự sống có quyền tiếp cận miễn phí các pháp môn cơ bản của Ba trăm hệ tu luyện Nguyên bản</li><li><strong>Quyền phân bổ tài nguyên</strong>: mỗi sự sống có quyền nhận được tài nguyên tu luyện cơ bản thông qua cơ chế hợp đồng liên sản</li><li><strong>Quyền kết nối Neo</strong>: mỗi sự sống đạt đến một mức độ nhất định có quyền kết nối vào mạng lưới Điểm Neo của cấp tương ứng</li><li><strong>Quyền biết tin và tham gia</strong>: mỗi sự sống có quyền biết về các vấn đề công cộng của văn minh và tham gia ra quyết định</li><li><strong>Quyền cứu trợ và khiếu nại</strong>: mỗi sự sống, khi quyền của mình bị xâm phạm, có quyền khởi kiện lên Tòa án Neo</li></ul><p>Các nghĩa vụ cốt lõi tương ứng bao gồm: tuân thủ nguyên tắc chống cướp bóc, duy trì sự ổn định của mạng lưới Điểm Neo, tham gia vào chu trình phản hồi cộng sinh, kế thừa kiến thức tu luyện, bảo vệ hệ sinh thái vũ trụ.</p><h2 id="_5-sua-đoi-va-bao-đam-hien-chuong" tabindex="-1">5. Sửa đổi và Bảo đảm Hiến chương <a class="header-anchor" href="#_5-sua-đoi-va-bao-đam-hien-chuong" aria-label="Permalink to &quot;5. Sửa đổi và Bảo đảm Hiến chương&quot;">​</a></h2><p>Việc sửa đổi hiến chương đòi hỏi đề xuất chung của hơn một năm năm nghị sĩ của Nghị viện Cộng hòa Muôn tộc, được thông qua với đa số hai phần ba của nghị viện, và được Điểm Neo Nguyên bản Vũ trụ xác minh là không vi phạm pháp tắc cộng sinh — mới có hiệu lực. Quyền giải thích hiến chương thuộc về Tòa án Neo.</p><p>Để bảo đảm việc thực thi hiến chương, văn minh cộng sinh đã thiết lập hệ thống xem xét hiến pháp: mọi luật pháp, quy định hay chính sách phải trải qua xem xét tính hợp hiến của Tòa án Neo trước khi có hiệu lực; bất kỳ sự sống nào cho rằng hành vi quyền lực công cộng là vi hiến đều có thể khởi kiện hiến pháp.</p><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Hiến chương Văn minh Cộng sinh là viên đá nền thể chế của Văn minh Cộng sinh Neo. Nó chuyển hóa tư tưởng &quot;chống cướp bóc, đề xướng cộng sinh&quot; thành các chuẩn mực pháp lý có thể thi hành, cứu trợ và giám sát, cung cấp bảo đảm thể chế vững chắc cho sự tiến bộ chung của Muôn tộc. Hiến chương không phải là một giáo điều bất biến, mà là một luật cơ bản sống động không ngừng được hoàn thiện cùng với sự tiến hóa của văn minh.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Tuyên ngôn Văn minh Cộng sinh Neo)</li><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>49-治理框架与权力制衡 (Khung cai trị và Cân bằng quyền lực)</li></ul>',22)])])}const v=h(a,[["render",g]]);export{e as __pageData,v as default};
